-- prisma/seed.sql: made-up sample data for CreatorCrowdHub. Never for a live database.
-- Where it is loaded: a review copy and a public preview of this site, the staging database
-- when the owner presses "Load sample data" (never their live one), and your own machine with
-- `npm run db:seed`. No users: people sign up. Safe to run twice, all or nothing.
-- "Clara Coaching": five events (a past online AMA, a paid in-person workshop, an invite-led
-- online mastermind, a hybrid breakfast and a draft), their RSVPs, invites, polls, messages and
-- page views. Every person is made up and every address is @example.com. Dates follow now().
-- Generated with fixed keys: re-running adds nothing (ON CONFLICT DO NOTHING).
-- Every stamp is date_trunc('milliseconds', now()) plus or minus an interval: whole milliseconds, like the app's own
-- writes, so the keyset cursors (src/lib/text.ts keysetAfter) never skip or repeat a sample row.
BEGIN;

-- Stop when real data is there: this site already has events of its own.
DO $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM "events"
    WHERE "id" NOT IN ('a4cbc81f-36c4-4299-b3d7-b2843ee8ac50',
                       '6aa1fa14-889b-43e6-92c4-9e7887940f56',
                       'dc7a8613-a991-41b9-b90e-0487ad363d09',
                       'a1b1f1de-2487-4b06-9d8f-053ea090862a',
                       '8b3c74ca-5384-461f-bcdc-be7339d95022')
  ) THEN
    RAISE EXCEPTION 'prisma/seed.sql is sample data and this site already has events of its own. Nothing was changed.';
  END IF;
END $$;

-- Events
ON CONFLICT DO NOTHING;

-- Tickets: the workshop is the paid one ($49).
ON CONFLICT DO NOTHING;

-- RSVP questions
ON CONFLICT DO NOTHING;

-- Reminder rules (the defaults a new event gets)
ON CONFLICT DO NOTHING;

-- Invites to the mastermind
ON CONFLICT DO NOTHING;

-- RSVPs: going, maybe, declined, cancelled, waitlisted and awaiting payment. manage_token is a hash.
ON CONFLICT DO NOTHING;

-- Answers to the RSVP questions
ON CONFLICT DO NOTHING;

-- Ticket orders (sample checkout ids): paid, one pending, one refunded
ON CONFLICT DO NOTHING;

-- Polls: a closed one with results, an open one taking votes, a draft
ON CONFLICT DO NOTHING;

ON CONFLICT DO NOTHING;

ON CONFLICT DO NOTHING;

-- Messages sent to guests, and their deliveries (plus invite and confirmation emails)
ON CONFLICT DO NOTHING;

ON CONFLICT DO NOTHING;

-- Page views for the last 30 days of the published events, added once per event.
SELECT
  md5('sample-view:' || e.slug || ':' || d || ':' || v)::uuid,
  e.id,
  md5('sample-visitor:' || e.slug || ':' || d || ':' || v),
  (ARRAY[NULL, NULL, 'newsletter', 'instagram', 'linkedin'])[1 + (d + v) % 5],
  date_trunc('milliseconds', now()) - make_interval(days => d, hours => v % 12),
  ((date_trunc('milliseconds', now()) - make_interval(days => d, hours => v % 12)) AT TIME ZONE 'utc')::date
FROM (VALUES
    ('a4cbc81f-36c4-4299-b3d7-b2843ee8ac50'::uuid, 'ask-me-anything-pricing', 10),
    ('6aa1fa14-889b-43e6-92c4-9e7887940f56'::uuid, 'pricing-workshop', 8),
    ('dc7a8613-a991-41b9-b90e-0487ad363d09'::uuid, 'the-monthly-mastermind', 5),
    ('a1b1f1de-2487-4b06-9d8f-053ea090862a'::uuid, 'creator-breakfast', 4)
  ) AS e (id, slug, per_day)
  CROSS JOIN generate_series(0, 29) AS d
  CROSS JOIN LATERAL generate_series(0, GREATEST(1, e.per_day - (d % 4) - d / 6)) AS v
WHERE NOT EXISTS (SELECT 1 FROM "page_views" pv WHERE pv."event_id" = e.id)
ON CONFLICT DO NOTHING;

COMMIT;
