  ('a4cbc81f-36c4-4299-b3d7-b2843ee8ac50', 'ask-me-anything-pricing', 'Ask Me Anything: Pricing', E'Clara answers your pricing questions live.\n\nSubmit yours when you RSVP.', date_trunc('milliseconds', now()) - interval '216 hours', date_trunc('milliseconds', now()) - interval '214.5 hours', 'Europe/London', 'online', NULL, NULL, NULL, 'https://meet.example.com/clara-ama', 'public', 'published', 45, true, false, true, 0, false, 'D4ADCC', 'https://example.com/pricing-guide', 'ama', date_trunc('milliseconds', now()) - interval '1176 hours', date_trunc('milliseconds', now())),
  ('6aa1fa14-889b-43e6-92c4-9e7887940f56', 'pricing-workshop', 'Pricing Workshop', E'A hands-on half day: work out what to charge, then say it out loud.\n\nBring one offer you want to price.', date_trunc('milliseconds', now()) + interval '144 hours', date_trunc('milliseconds', now()) + interval '147 hours', 'America/Chicago', 'in_person', 'The Foundry', '200 W Adams St, Chicago, IL', 'https://maps.example.com/the-foundry', NULL, 'public', 'published', 12, true, false, true, 1, true, 'G6T5MB', NULL, 'workshop', date_trunc('milliseconds', now()) - interval '960 hours', date_trunc('milliseconds', now())),
  ('dc7a8613-a991-41b9-b90e-0487ad363d09', 'the-monthly-mastermind', 'The Monthly Mastermind', 'Peers, laptops and a tight agenda. Eight seats, hot seats rotate.', date_trunc('milliseconds', now()) + interval '288 hours', date_trunc('milliseconds', now()) + interval '289.5 hours', 'America/New_York', 'online', NULL, NULL, NULL, 'https://meet.example.com/clara-mastermind', 'public', 'published', 8, true, false, true, 0, false, 'WWZM2X', NULL, 'mastermind', date_trunc('milliseconds', now()) - interval '960 hours', date_trunc('milliseconds', now())),
  ('a1b1f1de-2487-4b06-9d8f-053ea090862a', 'creator-breakfast', 'Creator Breakfast', E'Coffee, pastries and an hour of swapping what is working.\n\nJoin in person or online.', date_trunc('milliseconds', now()) + interval '480 hours', date_trunc('milliseconds', now()) + interval '482 hours', 'Europe/London', 'hybrid', 'Studio One', '1 High Street, London', NULL, 'https://meet.example.com/clara-breakfast', 'public', 'published', 25, true, false, true, 2, true, 'UPE72G', NULL, 'breakfast', date_trunc('milliseconds', now()) - interval '960 hours', date_trunc('milliseconds', now())),
  ('8b3c74ca-5384-461f-bcdc-be7339d95022', 'launch-day-qa', 'Launch Day Q&A', 'Not published yet: a hybrid launch-day session.', date_trunc('milliseconds', now()) + interval '960 hours', date_trunc('milliseconds', now()) + interval '961 hours', 'Asia/Singapore', 'hybrid', 'Marina Hub', '10 Bayfront Ave, Singapore', NULL, 'https://meet.example.com/clara-launch', 'public', 'draft', NULL, true, false, true, 0, false, '48F5JE', NULL, 'launch', date_trunc('milliseconds', now()) - interval '960 hours', date_trunc('milliseconds', now()))
